namespace {
int checks=0;void check(bool v,const char* s){++checks;if(!v)throw std::runtime_error(s);}
StudyFact course(const StableId& actor,Integer start,Integer tick,Integer before,Integer gain){StudyFact f;f.actor_id=actor;f.start_tick=start;f.completed_tick=tick;f.phase="completed";f.terms.student_id=actor;f.terms.skill_id="commerce";f.terms.xp_before=before;f.terms.xp_limit=1200;f.terms.settlement_policy="per_lesson_v1";StudyLesson lesson;lesson.xp=gain;lesson.segment=StudySegment{1,tick,before,10000,gain,false,{},{}};f.lessons.push_back(lesson);return f;}
}
int main(){try{
    auto common_catalog=std::make_shared<CommonCatalog>();FamilyCatalog family_catalog;IdentityPrototype prototype;family_catalog.prototypes.insert("created_prototype",prototype);prototype.skills.commerce=290;family_catalog.prototypes.insert("adopted_prototype",prototype);prototype.skills.commerce=0;family_catalog.prototypes.insert("born_prototype",prototype);
    CommonState seed;seed.identity.world_id[0]=1;seed.identity.tick=5;seed.next_instance_id=100;seed.metadata.scenario_id="scenario";ActorRecord person;person.id="actor:20";person.prototype_id="created_prototype";person.created_tick=0;person.birth_tick=-14400;person.skills.commerce=310;seed.actors.insert(person.id,person);CommonStore common(seed,common_catalog);FamilyState family;FamilyBirthState births;GrowthState studies;GrowthSkillOriginContext context{*common_catalog,family_catalog,family,&births};
    common.state().facts.insert("private_shop:2",{"private_shop:2","private_shop_opened","private_shops"});CharacterCreationFact made;made.actor_id="actor:20";made.prototype_actor_id="created_prototype";made.scenario_id="scenario";made.draft.skills.commerce=290;family.facts.insert("family:18",made);family.facts.insert("actor:20",IdentityCreationFact{"created_prototype","actor:20",0,-14400,"Created","family:18",{}});common.state().facts.insert("family:18",{"family:18","family_character_creation","family"});common.state().facts.insert("actor:20",{"actor:20","actor_creation","family"});studies.facts.insert("action:30",course("actor:20",1,3,290,10));common.state().facts.insert("action:30",{"action:30","skill_study","cultivation"});common.state().facts.insert("private_shop:35",{"private_shop:35","private_shop_opened","private_shops"});
    auto source=read_growth_skill_origin(common,context,"actor:20","commerce");check(source.ok&&source.value.initial_xp==290&&source.value.origin_kind=="character_creation"&&source.value.source_fact_ids==std::vector<StableId>{"family:18","actor:20"},"own original draft not generic prototype or current XP");auto qualified=read_commerce_study_qualification(common,context,studies,"actor:20");check(qualified.ok&&qualified.value.minimum_xp==300&&qualified.value.minimum_level==2&&qualified.value.initial_source_ids==source.value.source_fact_ids,"created actor prior real study reaches opening level");qualified=read_commerce_study_qualification_before_opening(common,context,studies,"actor:20",4,"private_shop:35");check(qualified.ok&&qualified.value.minimum_xp==300,"cold opening same identity and study prefix");check(!read_commerce_study_qualification_before_opening(common,context,studies,"actor:20",4,"private_shop:2").ok,"later identity cannot fill an earlier opening");check(!read_commerce_study_qualification(common,*common_catalog,family_catalog,studies,"actor:20").ok,"old author-only overload unchanged");check(!read_growth_skill_origin(common,context,"actor:20","unknown").ok,"unknown skill not invented zero");
    person.id="actor:40";person.prototype_id="adopted_prototype";person.created_tick=2;person.birth_tick=-14400;person.skills.commerce=300;common.state().actors.insert(person.id,person);AdoptionFact adopted;adopted.kind="family_adoption";adopted.success=true;adopted.child_actor_id=person.id;adopted.completed_tick=2;adopted.terms.prototype_id="adopted_prototype";adopted.terms.birth_tick=-14400;family.facts.insert("action:36",adopted);family.facts.insert(person.id,IdentityCreationFact{"adopted_prototype",person.id,2,-14400,"Adopted","action:36",{}});common.state().facts.insert("action:36",{"action:36","family_adoption","family"});common.state().facts.insert(person.id,{person.id,"actor_creation","family"});studies.facts.insert("action:45",course(person.id,3,4,290,10));common.state().facts.insert("action:45",{"action:45","skill_study","cultivation"});qualified=read_commerce_study_qualification(common,context,studies,person.id);check(qualified.ok&&qualified.value.minimum_xp==300&&qualified.value.origin_kind=="adoption_creation","old adoption-generated person has original prototype and course chain");
    person.id="actor:70";person.prototype_id="born_prototype";person.created_tick=2;person.birth_tick=2;person.skills.commerce=10;common.state().actors.insert(person.id,person);FamilyBirthRecord born;born.actor_id=person.id;born.prototype_id="born_prototype";born.tick=2;births.births.insert("family_birth:68",born);common.state().facts.insert("family_birth:68",{"family_birth:68","family_birth_recorded","family_birth"});common.state().facts.insert(person.id,{person.id,"actor_creation","family_birth"});source=read_growth_skill_origin(common,context,person.id,"commerce");check(source.ok&&source.value.initial_xp==0&&source.value.origin_kind=="biological_birth","birth provenance not current trained XP");auto no_birth=context;no_birth.births=nullptr;check(!read_growth_skill_origin(common,no_birth,person.id,"commerce").ok,"missing birth ledger cannot infer provenance");common.state().actors.find(person.id)->birth_tick=1;check(!read_growth_skill_origin(common,context,person.id,"commerce").ok,"birth time must be original recorded birth");common.state().actors.find(person.id)->birth_tick=2;
    auto* adopted_study=std::get_if<StudyFact>(studies.facts.find("action:45"));adopted_study->start_tick=1;check(!read_commerce_study_qualification(common,context,studies,"actor:40").ok,"course cannot predate created person");adopted_study->start_tick=3;auto* created=std::get_if<IdentityCreationFact>(family.facts.find("actor:20"));created->source="family:99";check(!read_growth_skill_origin(common,context,"actor:20","commerce").ok,"missing source not replaced by present person");
    std::cout<<"GROWTH_DYNAMIC_SKILL_ORIGIN "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& e){std::cerr<<"GROWTH_DYNAMIC_SKILL_ORIGIN "<<checks<<" checks 1 failure: "<<e.what()<<'\n';return 1;}}
